update oa_salary_record
other_bonus = #{otherBonus}, other_deduction = #{otherDeduction}, total_salary = #{totalSalary}, status = #{status}, update_by = #{updateBy}, remark = #{remark}, update_time = sysdate()
where salary_id = #{salaryId}

mapper.select:
select  

    and r.user_id = #{userId}
    and r.user_name like concat('%', #{userName}, '%')
    and r.salary_month = #{salaryMonth}
    and r.status = #{status}
    and r.shop_dept_id = #{shopDeptId}

        and r.shop_dept_id in

            #{scopeDeptId}



order by r.salary_month desc, r.user_id asc
